window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q73","domains":[5],"level":4,"tag":"Need","q":"A service request requirement includes eligibility conditions, required documents, and a response deadline. Which modeling approach best reduces ambiguity?","opts":["Use complementary models, such as a process model for flow and rules or data model for conditions and information","Write one long paragraph and leave the order of conditions implicit","Create a UI prototype and treat it as the complete specification","Document only the deadline because it is easiest to measure"],"answer":[0],"why":["Correct: Complementary models express flow, rules, and information where one view would leave gaps.","A long narrative with implicit logic can obscure sequencing and conditions.","Correct: complementary views reduce ambiguity across process and rule or information needs.","A prototype may explore a solution but omit rules, data, and exceptions."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q74","domains":[5],"level":4,"tag":"Need","q":"A requirement is measurable and consistent with the proposed design, but does not contribute to the stated business objective. What should the BA conclude?","opts":["It is valid because it can be tested","Resolve its alignment with the need and objective before accepting it as valid","It is valid because the design already includes it","Raise its priority to keep the design unchanged"],"answer":[1],"why":["A measurable requirement can still be irrelevant or misaligned.","Correct: Testability and design fit do not replace validation against the business need and objective.","A design choice does not prove support for the intended outcome.","Correct: resolve alignment with the need and objective before accepting the requirement."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q75","domains":[5],"level":4,"tag":"Need","q":"A remote elicitation concerns a safety-critical exception process. Connectivity is limited and some participants cannot share screens. What is the best preparation?","opts":["Keep the planned tool and ask participants to reconnect until it works","Replace the session with email approval of proposed rules","Identify objectives and participation constraints, then select accessible techniques and materials","Limit participation to people with reliable connectivity and infer the rest"],"answer":[2],"why":["Persisting with inaccessible technology may prevent effective participation.","Correct: accessible methods matched to objectives help gather information inclusively.","Correct: Preparation accounts for objectives, participants, and constraints so the method produces usable information.","Approval of proposed rules presumes answers and may not elicit nuanced exceptions."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q76","domains":[5],"level":4,"tag":"Need","q":"A deadline is fixed, user-value evidence is incomplete, and two requirements share a dependency. What should inform the initial ranking?","opts":["Rank solely by deadline and never revisit","Ask the sponsor to choose without documenting assumptions","Delay prioritization until all user-value evidence is complete","Make a provisional ranking from known value, urgency, risks, and dependencies, then revisit as evidence changes"],"answer":[3],"why":["A deadline matters but does not eliminate other factors or reassessment.","Waiting for perfect evidence can stall planning unnecessarily.","Correct: a provisional ranking guides work and can be updated as evidence improves.","Correct: Prioritization is iterative and uses available contextual evidence, including dependencies."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q77","domains":[5],"level":5,"tag":"Need","q":"A broad stakeholder group reviewed an elicitation summary. Some misunderstood a diagram, though they agreed with written notes. What is the most effective next step?","opts":["Use a walkthrough or alternate representation to confirm how participants interpret the process, then revise if needed","Treat written approval as sufficient because the diagram was supplementary","Replace the diagram with a detailed solution design","Ask the diagram’s author to certify its meaning"],"answer":[0],"why":["Correct: Confirmation tests stakeholder understanding of results; a walkthrough can expose representational misunderstandings.","Agreement with notes does not confirm understanding of a material diagram.","Correct: a walkthrough or alternate view can reveal and resolve misunderstanding.","A design does not confirm the elicited process and could introduce solution assumptions."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q78","domains":[5],"level":5,"tag":"Need","q":"Different models of a claims process imply different rules for when an application is complete. What is the strongest next action?","opts":["Keep both models and let implementation determine the rule","Reconcile the underlying need and business rules with stakeholders, then align the models","Choose the model with fewer steps because it is easier to implement","Convert one model into a design and discard the other without review"],"answer":[1],"why":["Leaving contradictory models shifts an unresolved decision into delivery.","Correct: Models should coherently represent the need; conflicting rules must be resolved rather than left to implementation.","Correct: reconciling need and rules lets stakeholders establish a consistent requirement.","Implementation ease does not establish which rule meets the need."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q79","domains":[5],"level":5,"tag":"Need","q":"A requirement meets its acceptance criteria, but updated evidence shows implementing it would undermine a more important business outcome. What should happen?","opts":["Accept it because the criteria are met","Change the acceptance criteria so the requirement passes more easily","Revalidate its alignment and consequences with relevant stakeholders and reconsider whether it remains appropriate","Defer the concern to solution evaluation"],"answer":[2],"why":["Meeting criteria shows conformance, not continued alignment with the need.","Correct: revalidate alignment and consequences with stakeholders as evidence changes.","Correct: Validation remains tied to needs and objectives; evidence may show a requirement no longer supports intended value.","Changing criteria to force a pass avoids the underlying concern."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q80","domains":[5],"level":5,"tag":"Need","q":"New evidence shows a top-ranked requirement has low adoption potential, while a dependent requirement is now time-critical. What is the best recommendation?","opts":["Preserve the original order so delivery remains predictable","Prioritize only by adoption potential and ignore the deadline","Move the top item to the bottom without discussion","Reprioritize with stakeholders using updated value, urgency, risk, and dependency information, and make the rationale explicit"],"answer":[3],"why":["Predictability does not justify preserving a ranking that no longer reflects evidence or urgency.","An unexplained unilateral change may overlook stakeholder impacts and trade-offs.","Correct: reassess transparently with stakeholders using current factors and dependencies.","Correct: Prioritization is ongoing; updated context and dependencies warrant reassessment."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-14.html"},{"id":"q81","domains":[5],"level":1,"tag":"Solution","q":"Several teams will share requirements for a service. What should the information-management approach define?","opts":["How BA information is organized, stored, accessed, maintained, and reused","Which vendor owns the final solution","Which requirement is approved first","A single workshop format for all stakeholders"],"answer":[0],"why":["Correct: The approach establishes how BA information is managed through its life cycle, including access, storage, maintenance, and reuse.","This choice focuses on “Which vendor owns the final solution” but does not fully address “How BA information is organized, stored, accessed, maintained, and reused.” The approach establishes how BA information is managed through its life cycle, including access, storage, maintenance, and reuse.","This choice focuses on “Which requirement is approved first” but does not fully address “How BA information is organized, stored, accessed, maintained, and reused.” The approach establishes how BA information is managed through its life cycle, including access, storage, maintenance, and reuse.","This choice focuses on “A single workshop format for all stakeholders” but does not fully address “How BA information is organized, stored, accessed, maintained, and reused.” The approach establishes how BA information is managed through its life cycle, including access, storage, maintenance, and reuse."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q82","domains":[5],"level":1,"tag":"Solution","q":"A product team and vendor use different repositories. What planning decision best supports information management?","opts":["Make the vendor replace its repository before work begins","Define how related information will be exchanged, identified, accessed, and maintained across repositories","Let each team use different labels and reconcile them at delivery","Copy all artifacts manually after the project ends"],"answer":[1],"why":["This choice focuses on “Make the vendor replace its repository before work begins” but does not fully address “Define how related information will be exchanged, identified, accessed, and maintained across repositories.” Defining exchange, identity, access, and maintenance supports consistency across repositories.","Correct: Defining exchange, identity, access, and maintenance supports consistency across repositories.","This choice focuses on “Let each team use different labels and reconcile them at delivery” but does not fully address “Define how related information will be exchanged, identified, accessed, and maintained across repositories.” Defining exchange, identity, access, and maintenance supports consistency across repositories.","This choice focuses on “Copy all artifacts manually after the project ends” but does not fully address “Define how related information will be exchanged, identified, accessed, and maintained across repositories.” Defining exchange, identity, access, and maintenance supports consistency across repositories."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q83","domains":[5],"level":1,"tag":"Solution","q":"A policy changes after a requirement is approved but before deployment. What should the BA do?","opts":["Leave the approved requirement unchanged and mention the policy elsewhere","Delete it and write a new requirement without a link","Update and maintain the requirement so it remains accurate and current, preserving useful history and relationships","Wait for users to report a production problem"],"answer":[2],"why":["This choice focuses on “Leave the approved requirement unchanged and mention the policy elsewhere” but does not fully address “Update and maintain the requirement so it remains accurate and current, preserving useful history and relationships.” Maintenance keeps requirements accurate and current through the life cycle while retaining useful management information.","This choice focuses on “Delete it and write a new requirement without a link” but does not fully address “Update and maintain the requirement so it remains accurate and current, preserving useful history and relationships.” Maintenance keeps requirements accurate and current through the life cycle while retaining useful management information.","Correct: Maintenance keeps requirements accurate and current through the life cycle while retaining useful management information.","This choice focuses on “Wait for users to report a production problem” but does not fully address “Update and maintain the requirement so it remains accurate and current, preserving useful history and relationships.” Maintenance keeps requirements accurate and current through the life cycle while retaining useful management information."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q84","domains":[5],"level":1,"tag":"Solution","q":"A unit wants to reuse a requirement from an earlier initiative. What should the BA verify?","opts":["That the original wording can be copied unchanged","That it has the same priority as before","That the previous sponsor still approves it","That it remains accurate in the new context, including relevant attributes and relationships"],"answer":[3],"why":["This choice focuses on “That the original wording can be copied unchanged” but does not fully address “That it remains accurate in the new context, including relevant attributes and relationships.” Reused requirements should remain accurate for the new context with relevant relationships maintained.","This choice focuses on “That it has the same priority as before” but does not fully address “That it remains accurate in the new context, including relevant attributes and relationships.” Reused requirements should remain accurate for the new context with relevant relationships maintained.","This choice focuses on “That the previous sponsor still approves it” but does not fully address “That it remains accurate in the new context, including relevant attributes and relationships.” Reused requirements should remain accurate for the new context with relevant relationships maintained.","Correct: Reused requirements should remain accurate for the new context with relevant relationships maintained."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q85","domains":[5],"level":2,"tag":"Solution","q":"A stakeholder proposes changing a service-level requirement. What should traceability help identify?","opts":["Related needs, requirements, designs, and solution components that may be affected","Whether the change is automatically approved","Only the text immediately being edited","A replacement requirement with all links removed"],"answer":[0],"why":["Correct: Traceability reveals related work products and supports a complete impact analysis.","This choice focuses on “Whether the change is automatically approved” but does not fully address “Related needs, requirements, designs, and solution components that may be affected.” Traceability reveals related work products and supports a complete impact analysis.","This choice focuses on “Only the text immediately being edited” but does not fully address “Related needs, requirements, designs, and solution components that may be affected.” Traceability reveals related work products and supports a complete impact analysis.","This choice focuses on “A replacement requirement with all links removed” but does not fully address “Related needs, requirements, designs, and solution components that may be affected.” Traceability reveals related work products and supports a complete impact analysis."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q86","domains":[5],"level":2,"tag":"Solution","q":"Testing finds a solution component with no linked requirement. What is the best use of traceability?","opts":["Create a requirement after the fact so every component has a link","Investigate whether it supports an unstated need or is functionality without a justified requirement","Delete the component immediately","Trace business requirements only, excluding designs and components"],"answer":[1],"why":["This choice focuses on “Create a requirement after the fact so every component has a link” but does not fully address “Investigate whether it supports an unstated need or is functionality without a justified requirement.” Traceability can reveal unsupported functionality or missing requirements; investigate before deciding what to do.","Correct: Traceability can reveal unsupported functionality or missing requirements; investigate before deciding what to do.","This choice focuses on “Delete the component immediately” but does not fully address “Investigate whether it supports an unstated need or is functionality without a justified requirement.” Traceability can reveal unsupported functionality or missing requirements; investigate before deciding what to do.","This choice focuses on “Trace business requirements only, excluding designs and components” but does not fully address “Investigate whether it supports an unstated need or is functionality without a justified requirement.” Traceability can reveal unsupported functionality or missing requirements; investigate before deciding what to do."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q87","domains":[5],"level":2,"tag":"Solution","q":"A manager requests an extra approval step, claiming it will reduce errors. What should the BA assess before recommending action?","opts":["Whether it is easy to build","Whether the manager has already told the team to proceed","Its value and effects on related requirements, designs, scope, risks, and stakeholders","Whether an existing requirement can be deleted to make room"],"answer":[2],"why":["This choice focuses on “Whether it is easy to build” but does not fully address “Its value and effects on related requirements, designs, scope, risks, and stakeholders.” A proposed change is evaluated for value and impacts before deciding whether and how to act.","This choice focuses on “Whether the manager has already told the team to proceed” but does not fully address “Its value and effects on related requirements, designs, scope, risks, and stakeholders.” A proposed change is evaluated for value and impacts before deciding whether and how to act.","Correct: A proposed change is evaluated for value and impacts before deciding whether and how to act.","This choice focuses on “Whether an existing requirement can be deleted to make room” but does not fully address “Its value and effects on related requirements, designs, scope, risks, and stakeholders.” A proposed change is evaluated for value and impacts before deciding whether and how to act."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q88","domains":[5],"level":2,"tag":"Solution","q":"A new regulation conflicts with a requirement in development. What is the best next step?","opts":["Replace the requirement immediately and tell stakeholders after delivery","Treat the conflict as a design detail outside change assessment","Defer the regulatory change because development has started","Assess implications, affected relationships, risks, and value with stakeholders, then determine a response"],"answer":[3],"why":["This choice focuses on “Replace the requirement immediately and tell stakeholders after delivery” but does not fully address “Assess implications, affected relationships, risks, and value with stakeholders, then determine a response.” Assess the new information and impacts, then determine whether and how to address it.","This choice focuses on “Treat the conflict as a design detail outside change assessment” but does not fully address “Assess implications, affected relationships, risks, and value with stakeholders, then determine a response.” Assess the new information and impacts, then determine whether and how to address it.","This choice focuses on “Defer the regulatory change because development has started” but does not fully address “Assess implications, affected relationships, risks, and value with stakeholders, then determine a response.” Assess the new information and impacts, then determine whether and how to address it.","Correct: Assess the new information and impacts, then determine whether and how to address it."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q89","domains":[5],"level":3,"tag":"Solution","q":"A retailer wants fewer abandoned online orders. What belongs in defining the future state?","opts":["Desired outcomes, measurable objectives, and boundaries for changed enterprise capabilities","A selected checkout vendor and its features","A schedule of elicitation workshops","A list of current complaints without a desired outcome"],"answer":[0],"why":["Correct: The future state describes outcomes and boundaries that enable objectives and value.","This choice focuses on “A selected checkout vendor and its features” but does not fully address “Desired outcomes, measurable objectives, and boundaries for changed enterprise capabilities.” The future state describes outcomes and boundaries that enable objectives and value.","This choice focuses on “A schedule of elicitation workshops” but does not fully address “Desired outcomes, measurable objectives, and boundaries for changed enterprise capabilities.” The future state describes outcomes and boundaries that enable objectives and value.","This choice focuses on “A list of current complaints without a desired outcome” but does not fully address “Desired outcomes, measurable objectives, and boundaries for changed enterprise capabilities.” The future state describes outcomes and boundaries that enable objectives and value."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q90","domains":[5],"level":3,"tag":"Solution","q":"Leaders agree that the future claims service should improve customer experience. What is the most useful next step?","opts":["Use “better experience” as the only success statement","Define measurable objectives or acceptable conditions showing whether the future state addresses the need","Select the design most popular in a quick poll","Set an achievable target without checking its relevance to the need"],"answer":[1],"why":["This choice focuses on “Use “better experience” as the only success statement” but does not fully address “Define measurable objectives or acceptable conditions showing whether the future state addresses the need.” Measurable objectives and conditions make the future state assessable against the need.","Correct: Measurable objectives and conditions make the future state assessable against the need.","This choice focuses on “Select the design most popular in a quick poll” but does not fully address “Define measurable objectives or acceptable conditions showing whether the future state addresses the need.” Measurable objectives and conditions make the future state assessable against the need.","This choice focuses on “Set an achievable target without checking its relevance to the need” but does not fully address “Define measurable objectives or acceptable conditions showing whether the future state addresses the need.” Measurable objectives and conditions make the future state assessable against the need."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q91","domains":[5],"level":3,"tag":"Solution","q":"A migration failure is unlikely but could stop a legally required service. How should the BA characterize it?","opts":["Low risk because its probability is low","High risk only if it has already occurred","Assess likelihood and consequences; severe impact can make the risk significant despite low probability","Treat the uncertainty as a requirement rather than a risk"],"answer":[2],"why":["This choice focuses on “Low risk because its probability is low” but does not fully address “Assess likelihood and consequences; severe impact can make the risk significant despite low probability.” Risk assessment considers both likelihood and impact, including unlikely events with severe consequences.","This choice focuses on “High risk only if it has already occurred” but does not fully address “Assess likelihood and consequences; severe impact can make the risk significant despite low probability.” Risk assessment considers both likelihood and impact, including unlikely events with severe consequences.","Correct: Risk assessment considers both likelihood and impact, including unlikely events with severe consequences.","This choice focuses on “Treat the uncertainty as a requirement rather than a risk” but does not fully address “Assess likelihood and consequences; severe impact can make the risk significant despite low probability.” Risk assessment considers both likelihood and impact, including unlikely events with severe consequences."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q92","domains":[5],"level":3,"tag":"Solution","q":"A key vendor announces a possible service shutdown during implementation. What should the BA do?","opts":["Keep the original risk rating until shutdown is confirmed","Record the announcement as an issue and exclude it from risk analysis","Replace the vendor immediately without comparing implications","Reassess likelihood and impact on the future state and value, then work with stakeholders on responses"],"answer":[3],"why":["This choice focuses on “Keep the original risk rating until shutdown is confirmed” but does not fully address “Reassess likelihood and impact on the future state and value, then work with stakeholders on responses.” New information can change likelihood, impact, and response needs, so reassess with stakeholders.","This choice focuses on “Record the announcement as an issue and exclude it from risk analysis” but does not fully address “Reassess likelihood and impact on the future state and value, then work with stakeholders on responses.” New information can change likelihood, impact, and response needs, so reassess with stakeholders.","This choice focuses on “Replace the vendor immediately without comparing implications” but does not fully address “Reassess likelihood and impact on the future state and value, then work with stakeholders on responses.” New information can change likelihood, impact, and response needs, so reassess with stakeholders.","Correct: New information can change likelihood, impact, and response needs, so reassess with stakeholders."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q93","domains":[5],"level":4,"tag":"Solution","q":"A requirement states, “Reject incomplete applications.” What should the BA clarify and model?","opts":["Definition of incomplete, applicable exceptions, and expected outcomes","Color of the rejection message","Database technology for storing applications","Order in which developers should build screens"],"answer":[0],"why":["Correct: Clarifying conditions, exceptions, and outcomes makes the requirement unambiguous and modelable.","This choice focuses on “Color of the rejection message” but does not fully address “Definition of incomplete, applicable exceptions, and expected outcomes.” Clarifying conditions, exceptions, and outcomes makes the requirement unambiguous and modelable.","This choice focuses on “Database technology for storing applications” but does not fully address “Definition of incomplete, applicable exceptions, and expected outcomes.” Clarifying conditions, exceptions, and outcomes makes the requirement unambiguous and modelable.","This choice focuses on “Order in which developers should build screens” but does not fully address “Definition of incomplete, applicable exceptions, and expected outcomes.” Clarifying conditions, exceptions, and outcomes makes the requirement unambiguous and modelable."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q94","domains":[5],"level":4,"tag":"Solution","q":"A requirement spans a user journey, decision rules, and data attributes. Which modeling practice is strongest?","opts":["Force every detail into one process diagram","Use suitable complementary models and keep their meanings consistent","Create separate models without checking for conflicts","Use a clickable prototype as the only representation"],"answer":[1],"why":["This choice focuses on “Force every detail into one process diagram” but does not fully address “Use suitable complementary models and keep their meanings consistent.” Complementary models clarify different aspects while consistency keeps the requirement coherent.","Correct: Complementary models clarify different aspects while consistency keeps the requirement coherent.","This choice focuses on “Create separate models without checking for conflicts” but does not fully address “Use suitable complementary models and keep their meanings consistent.” Complementary models clarify different aspects while consistency keeps the requirement coherent.","This choice focuses on “Use a clickable prototype as the only representation” but does not fully address “Use suitable complementary models and keep their meanings consistent.” Complementary models clarify different aspects while consistency keeps the requirement coherent."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q95","domains":[5],"level":4,"tag":"Solution","q":"A program has business goals, stakeholder needs, solution requirements, and components. What is the purpose of defining requirements architecture?","opts":["Create the development release calendar","Select a vendor for each component","Organize related requirements and designs and show their relationships across levels and components","Write a separate detailed requirement for every stakeholder statement"],"answer":[2],"why":["This choice focuses on “Create the development release calendar” but does not fully address “Organize related requirements and designs and show their relationships across levels and components.” Requirements architecture structures requirements and designs and makes their relationships understandable.","This choice focuses on “Select a vendor for each component” but does not fully address “Organize related requirements and designs and show their relationships across levels and components.” Requirements architecture structures requirements and designs and makes their relationships understandable.","Correct: Requirements architecture structures requirements and designs and makes their relationships understandable.","This choice focuses on “Write a separate detailed requirement for every stakeholder statement” but does not fully address “Organize related requirements and designs and show their relationships across levels and components.” Requirements architecture structures requirements and designs and makes their relationships understandable."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q96","domains":[5],"level":4,"tag":"Solution","q":"Two teams model the same capability differently: one as a business rule, the other as a user requirement. What should the BA do?","opts":["Keep models separate because each team owns its view","Convert both to one user story without examining relationships","Choose the more detailed model and delete the other","Clarify architecture and reconcile terminology, relationships, and levels across the models"],"answer":[3],"why":["This choice focuses on “Keep models separate because each team owns its view” but does not fully address “Clarify architecture and reconcile terminology, relationships, and levels across the models.” Architecture supports coherent relationships and consistent understanding across requirements and designs.","This choice focuses on “Convert both to one user story without examining relationships” but does not fully address “Clarify architecture and reconcile terminology, relationships, and levels across the models.” Architecture supports coherent relationships and consistent understanding across requirements and designs.","This choice focuses on “Choose the more detailed model and delete the other” but does not fully address “Clarify architecture and reconcile terminology, relationships, and levels across the models.” Architecture supports coherent relationships and consistent understanding across requirements and designs.","Correct: Architecture supports coherent relationships and consistent understanding across requirements and designs."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q97","domains":[5],"level":5,"tag":"Solution","q":"A need is agreed, but stakeholders disagree on how to meet it. What should the BA do?","opts":["Develop feasible design options that could satisfy the need and compare them against relevant criteria","Document the sponsor’s preferred design as the only option","Ask developers to select the cheapest implementation","Wait for a vendor to propose a complete solution"],"answer":[0],"why":["Correct: Defining design options explores alternatives before recommending a solution.","This choice focuses on “Document the sponsor’s preferred design as the only option” but does not fully address “Develop feasible design options that could satisfy the need and compare them against relevant criteria.” Defining design options explores alternatives before recommending a solution.","This choice focuses on “Ask developers to select the cheapest implementation” but does not fully address “Develop feasible design options that could satisfy the need and compare them against relevant criteria.” Defining design options explores alternatives before recommending a solution.","This choice focuses on “Wait for a vendor to propose a complete solution” but does not fully address “Develop feasible design options that could satisfy the need and compare them against relevant criteria.” Defining design options explores alternatives before recommending a solution."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q98","domains":[5],"level":5,"tag":"Solution","q":"Two designs meet core requirements; one costs less but carries higher operating risk. How should the BA support a recommendation?","opts":["Choose the cheaper option because both meet core requirements","Compare value, cost, risk, feasibility, and stakeholder criteria, then explain the trade-offs","Choose the option with the most features","Ask the sponsor to decide without comparative impacts"],"answer":[1],"why":["This choice focuses on “Choose the cheaper option because both meet core requirements” but does not fully address “Compare value, cost, risk, feasibility, and stakeholder criteria, then explain the trade-offs.” Comparing options against relevant criteria makes trade-offs and potential value explicit.","Correct: Comparing options against relevant criteria makes trade-offs and potential value explicit.","This choice focuses on “Choose the option with the most features” but does not fully address “Compare value, cost, risk, feasibility, and stakeholder criteria, then explain the trade-offs.” Comparing options against relevant criteria makes trade-offs and potential value explicit.","This choice focuses on “Ask the sponsor to decide without comparative impacts” but does not fully address “Compare value, cost, risk, feasibility, and stakeholder criteria, then explain the trade-offs.” Comparing options against relevant criteria makes trade-offs and potential value explicit."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q99","domains":[5],"level":5,"tag":"Solution","q":"A solution meets its performance target, but a low-cost configuration change could remove a recurring user workaround. What should the BA recommend?","opts":["Implement the configuration immediately without validating the workaround","Leave the solution unchanged because it meets its current target","Assess likely value, impacts, and feasibility with stakeholders before recommending the targeted change","Replace the whole solution to maximize improvement"],"answer":[2],"why":["This choice focuses on “Implement the configuration immediately without validating the workaround” but does not fully address “Assess likely value, impacts, and feasibility with stakeholders before recommending the targeted change.” A targeted action may increase value, but assess benefits, impacts, and feasibility first.","This choice focuses on “Leave the solution unchanged because it meets its current target” but does not fully address “Assess likely value, impacts, and feasibility with stakeholders before recommending the targeted change.” A targeted action may increase value, but assess benefits, impacts, and feasibility first.","Correct: A targeted action may increase value, but assess benefits, impacts, and feasibility first.","This choice focuses on “Replace the whole solution to maximize improvement” but does not fully address “Assess likely value, impacts, and feasibility with stakeholders before recommending the targeted change.” A targeted action may increase value, but assess benefits, impacts, and feasibility first."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q100","domains":[5],"level":5,"tag":"Solution","q":"Analysis identifies training, a costly redesign, and a data correction as possible value improvements. What is the best recommendation approach?","opts":["Recommend redesign because it is the largest visible change","Present options without linking them to performance evidence or stakeholder needs","Recommend training because it is cheapest, regardless of the value gap","Compare expected value, costs, risks, and impacts, then recommend a justified sequence or combination"],"answer":[3],"why":["This choice focuses on “Recommend redesign because it is the largest visible change” but does not fully address “Compare expected value, costs, risks, and impacts, then recommend a justified sequence or combination.” Recommendations should connect actions to evidence and compare likely value and implications.","This choice focuses on “Present options without linking them to performance evidence or stakeholder needs” but does not fully address “Compare expected value, costs, risks, and impacts, then recommend a justified sequence or combination.” Recommendations should connect actions to evidence and compare likely value and implications.","This choice focuses on “Recommend training because it is cheapest, regardless of the value gap” but does not fully address “Compare expected value, costs, risks, and impacts, then recommend a justified sequence or combination.” Recommendations should connect actions to evidence and compare likely value and implications.","Correct: Recommendations should connect actions to evidence and compare likely value and implications."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-15.html"},{"id":"q101","domains":[5],"level":1,"tag":"Solution","q":"A program stores sensitive requirements, designs, and decision records in several tools. What should its information-management approach define first?","opts":["Define information classifications, access, retention, ownership, and how related items are maintained","Select one tool and require every team to use it immediately","Set the approval sequence for each requirement","Ask each analyst to decide access case by case"],"answer":[0],"why":["Correct: Correct: management rules should identify how information is classified, accessed, maintained, and retained in the context of the initiative.","This option focuses on “Select one tool and require every team to use it immediately” but does not fully address “Define information classifications, access, retention, ownership, and how related items are maintained.” Correct: management rules should identify how information is classified, accessed, maintained, and retained in the context of the initiative.","This option focuses on “Set the approval sequence for each requirement” but does not fully address “Define information classifications, access, retention, ownership, and how related items are maintained.” Correct: management rules should identify how information is classified, accessed, maintained, and retained in the context of the initiative.","This option focuses on “Ask each analyst to decide access case by case” but does not fully address “Define information classifications, access, retention, ownership, and how related items are maintained.” Correct: management rules should identify how information is classified, accessed, maintained, and retained in the context of the initiative."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q102","domains":[5],"level":1,"tag":"Solution","q":"A supplier sends requirement files with identifiers that conflict with the client repository. What is the best planning response?","opts":["Rename the supplier’s records on import without preserving old identifiers","Agree on metadata, identifiers, exchange rules, and responsibility for maintaining links across repositories","Keep both sets of identifiers and let each team use its own","Wait until final delivery to reconcile the repositories"],"answer":[1],"why":["This option focuses on “Rename the supplier’s records on import without preserving old identifiers” but does not fully address “Agree on metadata, identifiers, exchange rules, and responsibility for maintaining links across repositories.” Correct: shared conventions and responsibilities support usable, identifiable, and maintainable information across repositories.","Correct: Correct: shared conventions and responsibilities support usable, identifiable, and maintainable information across repositories.","This option focuses on “Keep both sets of identifiers and let each team use its own” but does not fully address “Agree on metadata, identifiers, exchange rules, and responsibility for maintaining links across repositories.” Correct: shared conventions and responsibilities support usable, identifiable, and maintainable information across repositories.","This option focuses on “Wait until final delivery to reconcile the repositories” but does not fully address “Agree on metadata, identifiers, exchange rules, and responsibility for maintaining links across repositories.” Correct: shared conventions and responsibilities support usable, identifiable, and maintainable information across repositories."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q103","domains":[5],"level":1,"tag":"Solution","q":"A requirement is revised after a legal interpretation changes. Several teams still reference the prior version. What should the BA do?","opts":["Replace the requirement everywhere without retaining the earlier version","Freeze the requirement because it was already approved","Maintain the requirement’s accurate current version and preserve appropriate history and links so teams can identify the applicable one","Send an informal email but leave the repository unchanged"],"answer":[2],"why":["This option focuses on “Replace the requirement everywhere without retaining the earlier version” but does not fully address “Maintain the requirement’s accurate current version and preserve appropriate history and links so teams can identify the applicable one.” Correct: maintaining requirements keeps them accurate and current while supporting controlled use and reuse of information.","This option focuses on “Freeze the requirement because it was already approved” but does not fully address “Maintain the requirement’s accurate current version and preserve appropriate history and links so teams can identify the applicable one.” Correct: maintaining requirements keeps them accurate and current while supporting controlled use and reuse of information.","Correct: Correct: maintaining requirements keeps them accurate and current while supporting controlled use and reuse of information.","This option focuses on “Send an informal email but leave the repository unchanged” but does not fully address “Maintain the requirement’s accurate current version and preserve appropriate history and links so teams can identify the applicable one.” Correct: maintaining requirements keeps them accurate and current while supporting controlled use and reuse of information."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q104","domains":[5],"level":1,"tag":"Solution","q":"A requirement is copied from a similar product into a new market. Which maintenance action is most important?","opts":["Reuse it as-is because the product is similar","Delete its source link so it appears locally owned","Change only its priority to match the new release","Assess its accuracy and relevance in this context and update needed attributes or relationships"],"answer":[3],"why":["This option focuses on “Reuse it as-is because the product is similar” but does not fully address “Assess its accuracy and relevance in this context and update needed attributes or relationships.” Correct: reuse depends on the requirement remaining accurate and relevant in its new context, with useful relationships maintained.","This option focuses on “Delete its source link so it appears locally owned” but does not fully address “Assess its accuracy and relevance in this context and update needed attributes or relationships.” Correct: reuse depends on the requirement remaining accurate and relevant in its new context, with useful relationships maintained.","This option focuses on “Change only its priority to match the new release” but does not fully address “Assess its accuracy and relevance in this context and update needed attributes or relationships.” Correct: reuse depends on the requirement remaining accurate and relevant in its new context, with useful relationships maintained.","Correct: Correct: reuse depends on the requirement remaining accurate and relevant in its new context, with useful relationships maintained."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q105","domains":[5],"level":2,"tag":"Solution","q":"A stakeholder asks to change a response-time requirement. What should the BA do with traceability before estimating impacts?","opts":["Trace the requirement to its source need and related designs, components, and tests","Check only the requirement’s latest approval date","Ask developers to estimate from the sentence alone","Remove links that point to outdated designs"],"answer":[0],"why":["Correct: Correct: tracing related work products supports a more complete impact analysis of the proposed change.","This option focuses on “Check only the requirement’s latest approval date” but does not fully address “Trace the requirement to its source need and related designs, components, and tests.” Correct: tracing related work products supports a more complete impact analysis of the proposed change.","This option focuses on “Ask developers to estimate from the sentence alone” but does not fully address “Trace the requirement to its source need and related designs, components, and tests.” Correct: tracing related work products supports a more complete impact analysis of the proposed change.","This option focuses on “Remove links that point to outdated designs” but does not fully address “Trace the requirement to its source need and related designs, components, and tests.” Correct: tracing related work products supports a more complete impact analysis of the proposed change."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q106","domains":[5],"level":2,"tag":"Solution","q":"An audit finds an implemented notification with no link to a requirement or need. What is the best next action?","opts":["Create a new requirement to legitimize the notification","Investigate whether it supports an unstated need or is unsupported functionality before recommending action","Delete it immediately because no link exists","Add a link to the nearest requirement even if the relationship is unclear"],"answer":[1],"why":["This option focuses on “Create a new requirement to legitimize the notification” but does not fully address “Investigate whether it supports an unstated need or is unsupported functionality before recommending action.” Correct: traceability exposes unsupported functionality or missing requirements; investigate the actual need before deciding.","Correct: Correct: traceability exposes unsupported functionality or missing requirements; investigate the actual need before deciding.","This option focuses on “Delete it immediately because no link exists” but does not fully address “Investigate whether it supports an unstated need or is unsupported functionality before recommending action.” Correct: traceability exposes unsupported functionality or missing requirements; investigate the actual need before deciding.","This option focuses on “Add a link to the nearest requirement even if the relationship is unclear” but does not fully address “Investigate whether it supports an unstated need or is unsupported functionality before recommending action.” Correct: traceability exposes unsupported functionality or missing requirements; investigate the actual need before deciding."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q107","domains":[5],"level":2,"tag":"Solution","q":"Operations requests an extra verification step to reduce fraud, but it may lengthen service time. What should the BA evaluate?","opts":["Whether the team can add the step this week","Whether the requesting manager has already announced the change","Expected value and impacts on related requirements, workflow, risks, stakeholders, and scope","Whether another requirement can be removed to offset effort"],"answer":[2],"why":["This option focuses on “Whether the team can add the step this week” but does not fully address “Expected value and impacts on related requirements, workflow, risks, stakeholders, and scope.” Correct: a requested change should be assessed for value and effects before deciding whether and how to act.","This option focuses on “Whether the requesting manager has already announced the change” but does not fully address “Expected value and impacts on related requirements, workflow, risks, stakeholders, and scope.” Correct: a requested change should be assessed for value and effects before deciding whether and how to act.","Correct: Correct: a requested change should be assessed for value and effects before deciding whether and how to act.","This option focuses on “Whether another requirement can be removed to offset effort” but does not fully address “Expected value and impacts on related requirements, workflow, risks, stakeholders, and scope.” Correct: a requested change should be assessed for value and effects before deciding whether and how to act."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q108","domains":[5],"level":2,"tag":"Solution","q":"A stakeholder proposes replacing a planned report with a real-time dashboard. What should happen before committing?","opts":["Accept it because the stakeholder is a primary user","Ask the designer to build both alternatives","Reject it because the report was previously approved","Assess the proposed change’s value, scope, dependencies, costs, risks, and effects on related requirements"],"answer":[3],"why":["This option focuses on “Accept it because the stakeholder is a primary user” but does not fully address “Assess the proposed change’s value, scope, dependencies, costs, risks, and effects on related requirements.” Correct: evaluate the request and its impacts before deciding whether it belongs in the change.","This option focuses on “Ask the designer to build both alternatives” but does not fully address “Assess the proposed change’s value, scope, dependencies, costs, risks, and effects on related requirements.” Correct: evaluate the request and its impacts before deciding whether it belongs in the change.","This option focuses on “Reject it because the report was previously approved” but does not fully address “Assess the proposed change’s value, scope, dependencies, costs, risks, and effects on related requirements.” Correct: evaluate the request and its impacts before deciding whether it belongs in the change.","Correct: Correct: evaluate the request and its impacts before deciding whether it belongs in the change."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q109","domains":[5],"level":3,"tag":"Solution","q":"A city wants to reduce permit backlogs without lowering review quality. What should the future-state description include?","opts":["Desired outcomes, measurable objectives, and boundaries for the changed capabilities and processes","A preferred case-management product and its feature list","A detailed sprint plan for implementation","A list of current complaints without target outcomes"],"answer":[0],"why":["Correct: Correct: a future state describes outcomes and boundaries that support business objectives and potential value.","This option focuses on “A preferred case-management product and its feature list” but does not fully address “Desired outcomes, measurable objectives, and boundaries for the changed capabilities and processes.” Correct: a future state describes outcomes and boundaries that support business objectives and potential value.","This option focuses on “A detailed sprint plan for implementation” but does not fully address “Desired outcomes, measurable objectives, and boundaries for the changed capabilities and processes.” Correct: a future state describes outcomes and boundaries that support business objectives and potential value.","This option focuses on “A list of current complaints without target outcomes” but does not fully address “Desired outcomes, measurable objectives, and boundaries for the changed capabilities and processes.” Correct: a future state describes outcomes and boundaries that support business objectives and potential value."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q110","domains":[5],"level":3,"tag":"Solution","q":"Executives agree that a future service should be “more accessible.” What is the best next step?","opts":["Keep that phrase as the only future-state objective","Define measurable objectives or conditions that show how accessibility and the need will be satisfied","Select the design with the most accessibility features","Use the current service average as the future target without analysis"],"answer":[1],"why":["This option focuses on “Keep that phrase as the only future-state objective” but does not fully address “Define measurable objectives or conditions that show how accessibility and the need will be satisfied.” Correct: measurable objectives make the future state assessable and connect it to the need.","Correct: Correct: measurable objectives make the future state assessable and connect it to the need.","This option focuses on “Select the design with the most accessibility features” but does not fully address “Define measurable objectives or conditions that show how accessibility and the need will be satisfied.” Correct: measurable objectives make the future state assessable and connect it to the need.","This option focuses on “Use the current service average as the future target without analysis” but does not fully address “Define measurable objectives or conditions that show how accessibility and the need will be satisfied.” Correct: measurable objectives make the future state assessable and connect it to the need."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q111","domains":[5],"level":3,"tag":"Solution","q":"A supplier outage is unlikely but could interrupt a critical public service for several days. How should the BA assess it?","opts":["Treat it as low risk because the probability is low","Treat it as an issue only after the outage occurs","Assess likelihood and impact; severe consequences may make a low-probability event significant","Ignore it if the supplier has not breached its contract"],"answer":[2],"why":["This option focuses on “Treat it as low risk because the probability is low” but does not fully address “Assess likelihood and impact; severe consequences may make a low-probability event significant.” Correct: risk assessment considers both probability and impact, including severe consequences that have not occurred.","This option focuses on “Treat it as an issue only after the outage occurs” but does not fully address “Assess likelihood and impact; severe consequences may make a low-probability event significant.” Correct: risk assessment considers both probability and impact, including severe consequences that have not occurred.","Correct: Correct: risk assessment considers both probability and impact, including severe consequences that have not occurred.","This option focuses on “Ignore it if the supplier has not breached its contract” but does not fully address “Assess likelihood and impact; severe consequences may make a low-probability event significant.” Correct: risk assessment considers both probability and impact, including severe consequences that have not occurred."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q112","domains":[5],"level":3,"tag":"Solution","q":"A data-conversion risk cannot be eliminated, but a pilot can reveal defects before migration. What is the strongest response?","opts":["Accept the risk without further monitoring because it cannot be eliminated","Treat the pilot as proof that conversion risk is zero","Transfer responsibility to the vendor and stop assessing it","Plan a pilot as a mitigation, define evidence or thresholds, and monitor the remaining risk with stakeholders"],"answer":[3],"why":["This option focuses on “Accept the risk without further monitoring because it cannot be eliminated” but does not fully address “Plan a pilot as a mitigation, define evidence or thresholds, and monitor the remaining risk with stakeholders.” Correct: mitigation can reduce likelihood or impact, while residual risk still needs monitoring and stakeholder attention.","This option focuses on “Treat the pilot as proof that conversion risk is zero” but does not fully address “Plan a pilot as a mitigation, define evidence or thresholds, and monitor the remaining risk with stakeholders.” Correct: mitigation can reduce likelihood or impact, while residual risk still needs monitoring and stakeholder attention.","This option focuses on “Transfer responsibility to the vendor and stop assessing it” but does not fully address “Plan a pilot as a mitigation, define evidence or thresholds, and monitor the remaining risk with stakeholders.” Correct: mitigation can reduce likelihood or impact, while residual risk still needs monitoring and stakeholder attention.","Correct: Correct: mitigation can reduce likelihood or impact, while residual risk still needs monitoring and stakeholder attention."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q113","domains":[5],"level":4,"tag":"Solution","q":"A requirement says, “Escalate overdue cases promptly.” What should be clarified to make it useful?","opts":["What counts as overdue, what triggers escalation, the expected timing, and relevant exceptions","Which color should identify an escalated case","Which database will store the escalation flag","Which developer will implement the rule"],"answer":[0],"why":["Correct: Correct: explicit conditions, triggers, outcomes, and exceptions make the requirement understandable and analyzable.","This option focuses on “Which color should identify an escalated case” but does not fully address “What counts as overdue, what triggers escalation, the expected timing, and relevant exceptions.” Correct: explicit conditions, triggers, outcomes, and exceptions make the requirement understandable and analyzable.","This option focuses on “Which database will store the escalation flag” but does not fully address “What counts as overdue, what triggers escalation, the expected timing, and relevant exceptions.” Correct: explicit conditions, triggers, outcomes, and exceptions make the requirement understandable and analyzable.","This option focuses on “Which developer will implement the rule” but does not fully address “What counts as overdue, what triggers escalation, the expected timing, and relevant exceptions.” Correct: explicit conditions, triggers, outcomes, and exceptions make the requirement understandable and analyzable."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q114","domains":[5],"level":4,"tag":"Solution","q":"A loan requirement involves eligibility rules and a sequence of user actions. Which representation is most helpful?","opts":["One screen mock-up that implies both the rules and the sequence","Suitable complementary models, such as a decision model for eligibility and a process or use-case view for interaction","A component diagram chosen by developers","A prose statement that the loan process should be easy"],"answer":[1],"why":["This option focuses on “One screen mock-up that implies both the rules and the sequence” but does not fully address “Suitable complementary models, such as a decision model for eligibility and a process or use-case view for interaction.” Correct: complementary models clarify different aspects of the requirement without forcing one representation to carry everything.","Correct: Correct: complementary models clarify different aspects of the requirement without forcing one representation to carry everything.","This option focuses on “A component diagram chosen by developers” but does not fully address “Suitable complementary models, such as a decision model for eligibility and a process or use-case view for interaction.” Correct: complementary models clarify different aspects of the requirement without forcing one representation to carry everything.","This option focuses on “A prose statement that the loan process should be easy” but does not fully address “Suitable complementary models, such as a decision model for eligibility and a process or use-case view for interaction.” Correct: complementary models clarify different aspects of the requirement without forcing one representation to carry everything."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q115","domains":[5],"level":4,"tag":"Solution","q":"A business requirement changes, and several stakeholder requirements and design elements were derived from it. What does requirements architecture help the BA do?","opts":["Set a new project end date","Choose which team should implement each item","Identify and assess the relationships among the affected requirements and designs","Rewrite all derived requirements before checking whether they are affected"],"answer":[2],"why":["This option focuses on “Set a new project end date” but does not fully address “Identify and assess the relationships among the affected requirements and designs.” Correct: architecture makes relationships and levels visible, supporting impact assessment and coherent change.","This option focuses on “Choose which team should implement each item” but does not fully address “Identify and assess the relationships among the affected requirements and designs.” Correct: architecture makes relationships and levels visible, supporting impact assessment and coherent change.","Correct: Correct: architecture makes relationships and levels visible, supporting impact assessment and coherent change.","This option focuses on “Rewrite all derived requirements before checking whether they are affected” but does not fully address “Identify and assess the relationships among the affected requirements and designs.” Correct: architecture makes relationships and levels visible, supporting impact assessment and coherent change."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q116","domains":[5],"level":4,"tag":"Solution","q":"A solution has user, data, and process models maintained by different teams. What should the BA establish?","opts":["A list of models ordered by creation date","A single model that replaces every other representation","Separate ownership rules so teams never need to coordinate","A structure showing how the models and requirements relate, including consistent terminology and viewpoints"],"answer":[3],"why":["This option focuses on “A list of models ordered by creation date” but does not fully address “A structure showing how the models and requirements relate, including consistent terminology and viewpoints.” Correct: requirements architecture structures related representations and supports coherence across viewpoints.","This option focuses on “A single model that replaces every other representation” but does not fully address “A structure showing how the models and requirements relate, including consistent terminology and viewpoints.” Correct: requirements architecture structures related representations and supports coherence across viewpoints.","This option focuses on “Separate ownership rules so teams never need to coordinate” but does not fully address “A structure showing how the models and requirements relate, including consistent terminology and viewpoints.” Correct: requirements architecture structures related representations and supports coherence across viewpoints.","Correct: Correct: requirements architecture structures related representations and supports coherence across viewpoints."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q117","domains":[5],"level":5,"tag":"Solution","q":"A need is agreed, but two departments prefer different approaches. What should the BA do?","opts":["Develop feasible design options that could satisfy the need, then compare them using relevant criteria","Document the senior department’s preferred approach as the selected solution","Ask a vendor to choose the approach","Begin delivery on both approaches and compare after launch"],"answer":[0],"why":["Correct: Correct: defining design options explores alternative ways of satisfying the need before a recommendation is made.","This option focuses on “Document the senior department’s preferred approach as the selected solution” but does not fully address “Develop feasible design options that could satisfy the need, then compare them using relevant criteria.” Correct: defining design options explores alternative ways of satisfying the need before a recommendation is made.","This option focuses on “Ask a vendor to choose the approach” but does not fully address “Develop feasible design options that could satisfy the need, then compare them using relevant criteria.” Correct: defining design options explores alternative ways of satisfying the need before a recommendation is made.","This option focuses on “Begin delivery on both approaches and compare after launch” but does not fully address “Develop feasible design options that could satisfy the need, then compare them using relevant criteria.” Correct: defining design options explores alternative ways of satisfying the need before a recommendation is made."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q118","domains":[5],"level":5,"tag":"Solution","q":"Two feasible options meet the core need; one has lower initial cost while the other has lower operating risk. What should inform the recommendation?","opts":["Choose the lower initial cost because both meet the core need","Compare value, cost over time, risks, feasibility, and stakeholder impacts, then explain the trade-offs","Choose the option with more functions","Let the implementation team decide without an options comparison"],"answer":[1],"why":["This option focuses on “Choose the lower initial cost because both meet the core need” but does not fully address “Compare value, cost over time, risks, feasibility, and stakeholder impacts, then explain the trade-offs.” Correct: comparing alternatives against relevant criteria exposes trade-offs and potential value.","Correct: Correct: comparing alternatives against relevant criteria exposes trade-offs and potential value.","This option focuses on “Choose the option with more functions” but does not fully address “Compare value, cost over time, risks, feasibility, and stakeholder impacts, then explain the trade-offs.” Correct: comparing alternatives against relevant criteria exposes trade-offs and potential value.","This option focuses on “Let the implementation team decide without an options comparison” but does not fully address “Compare value, cost over time, risks, feasibility, and stakeholder impacts, then explain the trade-offs.” Correct: comparing alternatives against relevant criteria exposes trade-offs and potential value."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q119","domains":[5],"level":5,"tag":"Solution","q":"Performance data shows a service meets its average response target, but repeat contacts are rising for one customer group. What should the BA recommend?","opts":["Replace the service because the trend is unfavorable","Do nothing because the average target is met","Investigate the value gap and its cause, then assess targeted actions with affected stakeholders","Add a new target without examining why repeat contacts increased"],"answer":[2],"why":["This option focuses on “Replace the service because the trend is unfavorable” but does not fully address “Investigate the value gap and its cause, then assess targeted actions with affected stakeholders.” Correct: recommendations to increase solution value should address evidenced gaps and consider causes, impacts, and feasible actions.","This option focuses on “Do nothing because the average target is met” but does not fully address “Investigate the value gap and its cause, then assess targeted actions with affected stakeholders.” Correct: recommendations to increase solution value should address evidenced gaps and consider causes, impacts, and feasible actions.","Correct: Correct: recommendations to increase solution value should address evidenced gaps and consider causes, impacts, and feasible actions.","This option focuses on “Add a new target without examining why repeat contacts increased” but does not fully address “Investigate the value gap and its cause, then assess targeted actions with affected stakeholders.” Correct: recommendations to increase solution value should address evidenced gaps and consider causes, impacts, and feasible actions."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"},{"id":"q120","domains":[5],"level":5,"tag":"Solution","q":"Analysis finds training, a workflow change, and a costly replacement could improve value. How should the BA present recommendations?","opts":["Recommend replacement because it is the broadest change","List all three actions without linking them to performance evidence","Recommend training automatically because it costs least","Compare expected value, costs, risks, and stakeholder impacts, then recommend a justified action or sequence"],"answer":[3],"why":["This option focuses on “Recommend replacement because it is the broadest change” but does not fully address “Compare expected value, costs, risks, and stakeholder impacts, then recommend a justified action or sequence.” Correct: a recommendation should be supported by evidence and compare likely value and impacts of available actions.","This option focuses on “List all three actions without linking them to performance evidence” but does not fully address “Compare expected value, costs, risks, and stakeholder impacts, then recommend a justified action or sequence.” Correct: a recommendation should be supported by evidence and compare likely value and impacts of available actions.","This option focuses on “Recommend training automatically because it costs least” but does not fully address “Compare expected value, costs, risks, and stakeholder impacts, then recommend a justified action or sequence.” Correct: a recommendation should be supported by evidence and compare likely value and impacts of available actions.","Correct: Correct: a recommendation should be supported by evidence and compare likely value and impacts of available actions."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-20-timed-practice-set-16.html"}]);